parameters.jsCode:
// Die E-Mail-Domain ist der guenstigste Firmenschluessel, den ein Lead
// mitbringt: keine Zusatzabfrage noetig, und sie ist eindeutiger als ein
// frei getippter Firmenname ("Mueller GmbH" vs. "Müller G.m.b.H.").
const FREEMAILER = [
  'gmail.com', 'googlemail.com', 'gmx.de', 'gmx.net', 'gmx.at', 'gmx.ch',
  'web.de', 'freenet.de', 't-online.de', 'outlook.de', 'outlook.com',
  'hotmail.de', 'hotmail.com', 'live.de', 'yahoo.de', 'yahoo.com',
  'aol.com', 'icloud.com', 'me.com', 'mail.de', 'posteo.de', 'protonmail.com', 'proton.me'
];
// Wegwerfadressen sind kein Privatkunde, sondern meist gar kein Lead —
// deshalb getrennt gefuehrt und im Score spaeter bestraft.
const WEGWERF = ['mailinator.com', 'trashmail.com', 'wegwerfmail.de', '10minutemail.com', 'yopmail.com'];

const raus = [];
for (const eintrag of $input.all()) {
  const d = eintrag.json.body ?? eintrag.json;
  const email = String(d.email ?? '').trim().toLowerCase();
  const domain = email.includes('@') ? email.split('@').pop() : '';
  // Subdomains wie mail.firma.de auf die Hauptdomain zurueckfuehren, sonst
  // findet die Anreicherungs-API den Betrieb nicht.
  const teile = domain.split('.');
  const hauptdomain = teile.length > 2 && teile[teile.length - 2].length > 3
    ? teile.slice(-2).join('.')
    : domain;

  raus.push({
    json: {
      name: String(d.name ?? '').trim(),
      email,
      telefon: String(d.telefon ?? d.phone ?? '').replace(/[^0-9+]/g, ''),
      firma_angegeben: String(d.firma ?? d.company ?? '').trim(),
      nachricht: String(d.nachricht ?? d.message ?? '').trim(),
      quelle: String(d.quelle ?? 'Unbekannt').trim(),
      domain,
      hauptdomain,
      ist_freemailer: FREEMAILER.includes(domain),
      ist_wegwerfadresse: WEGWERF.includes(domain),
      eingegangen_am: new Date().toLocaleDateString('de-DE')
    }
  });
}
return raus;

