// Lead-Score 0-100, bewusst additiv und einzeln begruendet: Der Vertrieb
// sieht im CRM nicht nur die Zahl, sondern auch, welche Regel wie viele
// Punkte gegeben hat. Nur so laesst sich die Gewichtung spaeter ehrlich
// nachjustieren - eine Blackbox-Zahl wuerde nach zwei Wochen ignoriert.
const GROESSE_PUNKTE = {
  'Solo': 5,
  'Klein (2-9)': 10,
  'Mittel (10-49)': 25,
  'Gross (50-249)': 30,
  'Konzern (250+)': 20   // absichtlich weniger: lange Einkaufsprozesse
};
// Wunschbranchen des eigenen Betriebs - hier anpassen, das ist der
// wirksamste Hebel des ganzen Workflows.
const WUNSCHBRANCHEN = ['Maschinenbau', 'Handwerk', 'IT-Dienstleistung', 'Handel'];

const raus = [];
for (const eintrag of $input.all()) {
  const basis = $('E-Mail-Domain extrahieren').item.json;
  const j = eintrag.json;
  // Der KI-Node liefert je nach Version message.content oder das Objekt
  // direkt; der Freemail-Zweig liefert bereits fertige Felder.
  const ki = j.message?.content ?? j;

  const branche = String(ki.branche ?? j.branche ?? 'Sonstige');
  const groesse = String(ki.unternehmensgroesse ?? j.unternehmensgroesse ?? 'Klein (2-9)');
  const istB2B = Boolean(ki.b2b ?? j.b2b ?? false);

  let punkte = 0;
  const begruendung = [];
  const addiere = (p, text) => { punkte += p; begruendung.push((p >= 0 ? '+' : '') + p + ' ' + text); };

  if (istB2B) addiere(15, 'Geschaeftskunde');
  else addiere(0, 'Privatkunde oder B2B unklar');

  addiere(GROESSE_PUNKTE[groesse] ?? 5, 'Unternehmensgroesse: ' + groesse);

  if (WUNSCHBRANCHEN.includes(branche)) addiere(20, 'Wunschbranche: ' + branche);
  else addiere(5, 'Branche ausserhalb des Kernsegments: ' + branche);

  // Wer eine Telefonnummer hinterlaesst, rechnet mit einem Rueckruf -
  // in der Praxis das staerkste einzelne Kaufsignal im Formular.
  if (basis.telefon && basis.telefon.length >= 7) addiere(15, 'Telefonnummer hinterlassen');

  const laenge = (basis.nachricht || '').length;
  if (laenge >= 200) addiere(15, 'ausfuehrliche Anfrage (' + laenge + ' Zeichen)');
  else if (laenge >= 50) addiere(8, 'konkrete Anfrage (' + laenge + ' Zeichen)');
  else addiere(0, 'kaum Text in der Anfrage');

  // Kaufabsicht im Klartext schlaegt jede Firmenkennzahl.
  const signale = ['angebot', 'preis', 'kosten', 'anfrage', 'kaufen', 'beauftragen', 'termin', 'beratung'];
  const treffer = signale.filter(s => (basis.nachricht || '').toLowerCase().includes(s));
  if (treffer.length) addiere(Math.min(15, treffer.length * 5), 'Kaufsignal(e): ' + treffer.join(', '));

  if (basis.ist_wegwerfadresse) addiere(-40, 'Wegwerf-Mailadresse');
  if (!basis.name) addiere(-10, 'kein Name angegeben');

  punkte = Math.max(0, Math.min(100, punkte));
  const prioritaet = punkte >= 60 ? 'A' : punkte >= 35 ? 'B' : 'C';

  raus.push({
    json: {
      ...basis,
      kontakttyp: j.kontakttyp ?? (istB2B ? 'Firma' : 'Unklar'),
      branche,
      unternehmensgroesse: groesse,
      mitarbeiter_geschaetzt: ki.mitarbeiter_geschaetzt ?? null,
      b2b: istB2B,
      einordnung_begruendung: ki.begruendung ?? j.einordnung_begruendung ?? '',
      lead_score: punkte,
      prioritaet,
      score_begruendung: begruendung.join('; ')
    }
  });
}
return raus;

